(function() {
    'use strict';

    class CapstoneGlobalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Express Capstone GLOBAL';
            this.version = '1.2.0';
            this.START_CASH = 5000;
            this.FIN_FLOOR = -3000;
            this.FIN_CEIL = 9000;
            this.CAP_LOSS = 44;
            this.CAP_INSOLVENT = 20;
            this.MARKETS = [
                { id: 'mercado_central', name: 'Mercado Central', size: 52000, growth: 0.04, entryFee: 0, regPressure: 0.5, esgPressure: 0.7 },
                { id: 'region_andina', name: 'Región Andina', size: 14000, growth: 0.06, entryFee: 0, regPressure: 0.3, esgPressure: 0.5 },
                { id: 'cono_sur', name: 'Cono Sur', size: 11000, growth: 0.03, entryFee: 3000, regPressure: 0.7, esgPressure: 0.7 },
                { id: 'mercado_norte', name: 'Mercado del Norte', size: 38000, growth: 0.04, entryFee: 5000, regPressure: 0.8, esgPressure: 0.9 },
                { id: 'europa_occidental', name: 'Europa Occidental', size: 28000, growth: 0.02, entryFee: 6000, regPressure: 0.95, esgPressure: 0.95 },
                { id: 'europa_central', name: 'Europa Central', size: 19000, growth: 0.05, entryFee: 4000, regPressure: 0.8, esgPressure: 0.7 },
                { id: 'asia_sud', name: 'Asia del Sud', size: 48000, growth: 0.09, entryFee: 3500, regPressure: 0.2, esgPressure: 0.3 },
                { id: 'asia_sudeste', name: 'Asia Sudeste', size: 31000, growth: 0.08, entryFee: 4500, regPressure: 0.3, esgPressure: 0.3 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 5000,
                    esgRating: 45,
                    carbonIntensity: 100,
                    activeMarkets: ['mercado_central', 'region_andina'],
                    marketShares: { mercado_central: 20, region_andina: 12 },
                    profitHistory: [],
                    esgHistory: [],
                    revenueHistory: [],
                    carbonHistory: [],
                    lastEvent: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    sustainabilityPct: 3,
                    pricingStrategy: 'balanced',
                    productionMode: 'standard',
                    expandMarket: 'none'
                };
            }
            this._updateMarketOptions(state);
            this._updateEventPanel(state);
            this._syncControlsFromDecisions(state);
            this._applyEndState(state);
        }

        validateDecisions(decisions) {
            var sustainInput = document.getElementById('sustainInput');
            if (sustainInput) decisions.sustainabilityPct = parseFloat(sustainInput.value) || 0;

            var pricingSelect = document.getElementById('pricingSelect');
            if (pricingSelect) decisions.pricingStrategy = pricingSelect.value;

            var productionSelect = document.getElementById('productionSelect');
            if (productionSelect) decisions.productionMode = productionSelect.value;

            var expandSelect = document.getElementById('expandSelect');
            if (expandSelect) decisions.expandMarket = expandSelect.value;

            if (decisions.sustainabilityPct < 0 || decisions.sustainabilityPct > 15) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('sustain_warning'), 'warning'
                );
                return false;
            }

            if (decisions.expandMarket !== 'none') {
                var ds = window.mySimulation.state.domainState;
                var market = this._findMarket(decisions.expandMarket);
                if (market && ds.cash < market.entryFee) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('cash_warning'), 'warning'
                    );
                    return false;
                }
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var self = this;
            var period = state.currentPeriod;

            // 1. Revenue from active markets
            var totalRevenue = 0;
            var marketRevenues = {};

            ds.activeMarkets.forEach(function(mId) {
                var m = self._findMarket(mId);
                if (!m) return;
                var share = ds.marketShares[mId] || 0;
                var quarterRev = (m.size / 4) * (share / 100);

                // Organic share growth influenced by pricing and ESG fit
                var growthMod = 0.3;
                if (d.pricingStrategy === 'mass') growthMod = 0.5;
                if (d.pricingStrategy === 'premium') growthMod = 0.15;
                if (ds.esgRating > 60 && m.esgPressure > 0.6) growthMod += 0.2;
                ds.marketShares[mId] = Math.min(share + growthMod + 0.15, 35);

                // Apply market natural growth
                quarterRev *= (1 + m.growth / 4);

                marketRevenues[mId] = quarterRev;
                totalRevenue += quarterRev;
            });

            // 2. Pricing modifier
            var volumeMod = 1.0;
            var marginRate = 0.32;
            if (d.pricingStrategy === 'mass') { volumeMod = 1.15; marginRate = 0.24; }
            if (d.pricingStrategy === 'premium') { volumeMod = 0.82; marginRate = 0.42; }
            totalRevenue = totalRevenue * volumeMod;

            // 3. Production cost
            var prodCostMod = 1.0;
            if (d.productionMode === 'hybrid') prodCostMod = 1.10;
            if (d.productionMode === 'green') prodCostMod = 1.20;

            var baseCogs = totalRevenue * (1 - marginRate);
            var actualCogs = baseCogs * prodCostMod;
            var grossProfit = totalRevenue - actualCogs;

            // 4. Sustainability cost
            var sustainCost = totalRevenue * (d.sustainabilityPct / 100);

            // 5. Market expansion
            var entryCost = 0;
            var expandedName = '';
            if (d.expandMarket !== 'none') {
                var newMarket = this._findMarket(d.expandMarket);
                if (newMarket && ds.activeMarkets.indexOf(d.expandMarket) === -1) {
                    entryCost = newMarket.entryFee;
                    ds.activeMarkets.push(d.expandMarket);
                    ds.marketShares[d.expandMarket] = 3;
                    expandedName = newMarket.name;
                }
            }

            // 6. Geopolitical event effects
            var eventCost = 0;
            var eventMsg = '';

            if (period === 4) {
                if (ds.activeMarkets.indexOf('mercado_norte') !== -1) {
                    var tariffHit = (marketRevenues['mercado_norte'] || 0) * volumeMod * 0.18;
                    eventCost += tariffHit;
                    eventMsg = window.mySimulation.t('event_tariff_active');
                } else {
                    eventMsg = window.mySimulation.t('event_tariff_safe');
                }
            }

            if (period === 6) {
                var euActive = false;
                var euPenalty = 0;
                ['europa_occidental', 'europa_central'].forEach(function(eid) {
                    if (ds.activeMarkets.indexOf(eid) !== -1) {
                        euActive = true;
                        if (ds.carbonIntensity > 60) {
                            euPenalty += (marketRevenues[eid] || 0) * volumeMod * 0.15;
                        }
                    }
                });
                if (euActive && ds.carbonIntensity > 60) {
                    eventCost += euPenalty;
                    eventMsg = window.mySimulation.t('event_carbon_penalty');
                } else if (euActive) {
                    eventMsg = window.mySimulation.t('event_carbon_safe');
                } else {
                    eventMsg = window.mySimulation.t('event_carbon_safe');
                }
            }

            if (period === 8) {
                if (ds.esgRating < 60) {
                    eventCost += 2000;
                    ds.esgRating = Math.max(0, ds.esgRating - 8);
                    eventMsg = window.mySimulation.t('event_activist_penalty');
                } else {
                    ds.esgRating = Math.min(100, ds.esgRating + 3);
                    eventMsg = window.mySimulation.t('event_activist_safe');
                }
            }

            if (period === 10) {
                if (ds.activeMarkets.indexOf('asia_sudeste') !== -1) {
                    var geoHit = (marketRevenues['asia_sudeste'] || 0) * volumeMod * 0.30;
                    eventCost += geoHit;
                    eventMsg = window.mySimulation.t('event_geo_active');
                } else {
                    eventMsg = window.mySimulation.t('event_geo_safe');
                }
            }

            if (period === 12) {
                if (d.sustainabilityPct < 8) {
                    eventCost += totalRevenue * 0.12;
                    eventMsg = window.mySimulation.t('event_climate_penalty');
                } else {
                    eventMsg = window.mySimulation.t('event_climate_safe');
                }
            }

            // 7. Final profit
            var profit = grossProfit - sustainCost - entryCost - eventCost;

            // 8. Update ESG rating
            var esgChange = 0;
            esgChange += d.sustainabilityPct * 0.7;
            if (d.productionMode === 'green') esgChange += 3;
            if (d.productionMode === 'hybrid') esgChange += 1.5;
            if (d.productionMode === 'standard') esgChange -= 0.5;
            esgChange -= 0.8;
            if (d.pricingStrategy === 'premium') esgChange += 0.5;
            ds.esgRating = Math.max(0, Math.min(100, ds.esgRating + esgChange));

            // 9. Update carbon intensity
            var carbonChange = 0;
            if (d.productionMode === 'green') carbonChange = -7;
            if (d.productionMode === 'hybrid') carbonChange = -3.5;
            if (d.productionMode === 'standard') carbonChange = -0.3;
            carbonChange -= d.sustainabilityPct * 0.4;
            ds.carbonIntensity = Math.max(10, Math.round((ds.carbonIntensity + carbonChange) * 10) / 10);

            // 10. Update cash
            ds.cash = Math.round(ds.cash + profit);

            // 11. Store event
            ds.lastEvent = eventMsg;

            // 12. Push histories
            ds.profitHistory.push(Math.round(profit));
            ds.esgHistory.push(Math.round(ds.esgRating * 10) / 10);
            ds.revenueHistory.push(Math.round(totalRevenue));
            ds.carbonHistory.push(ds.carbonIntensity);

            // 13. Update dynamic UI after framework cycle
            setTimeout(function() {
                var st = window.mySimulation.state;
                self._updateMarketOptions(st);
                self._updateEventPanel(st);
                self._applyEndState(st);
            }, 500);

            return {
                period: period,
                revenue: Math.round(totalRevenue),
                profit: Math.round(profit),
                sustainCost: Math.round(sustainCost),
                entryCost: entryCost,
                eventCost: Math.round(eventCost),
                esgRating: Math.round(ds.esgRating * 10) / 10,
                carbonIntensity: ds.carbonIntensity,
                activeMarkets: ds.activeMarkets.length,
                expandedMarket: expandedName,
                eventMessage: eventMsg,
                cash: ds.cash
            };
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('esgDisplay', 'domainState.esgRating',
                (v) => self._getEsgGrade(v) + ' (' + Math.round(v) + ')');
            uiManager.bind('carbonDisplay', 'domainState.carbonIntensity',
                (v) => Math.round(v) + ' idx');
            uiManager.bind('marketsDisplay', 'domainState.activeMarkets',
                (v) => (v ? v.length : 0) + ' / 8');
            uiManager.bind('revenueDisplay', 'results.revenue',
                (v) => '$' + (v || 0).toLocaleString() + 'M');
            uiManager.bind('profitDisplay', 'results.profit',
                (v) => '$' + (v || 0).toLocaleString() + 'M');
        }

        getChartConfig() {
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            return {
                profitChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: T('chart_revenue'),
                                data: [],
                                borderColor: '#0d47a1',
                                backgroundColor: 'rgba(13,71,161,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: T('chart_profit'),
                                data: [],
                                borderColor: '#2e7d32',
                                backgroundColor: 'rgba(46,125,50,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: T('chart_fin_title') } },
                        scales: { y: { beginAtZero: true } }
                    }
                },
                esgChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: T('chart_esg'),
                                data: [],
                                borderColor: '#1565c0',
                                backgroundColor: 'rgba(21,101,192,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: T('chart_carbon'),
                                data: [],
                                borderColor: '#e65100',
                                backgroundColor: 'rgba(230,81,0,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: T('chart_esg_title') } },
                        scales: {
                            y: { beginAtZero: true, max: 100, position: 'left', title: { display: true, text: T('axis_esg') } },
                            y1: { beginAtZero: true, max: 120, position: 'right', title: { display: true, text: T('axis_carbon') }, grid: { drawOnChartArea: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var _q = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t('q_abbr') : 'Q';
            var ds = (state && state.domainState) ? state.domainState : {};
            var profitH  = ds.profitHistory  || [];
            var revenueH = ds.revenueHistory || [];
            var esgH     = ds.esgHistory     || [];
            var carbonH  = ds.carbonHistory  || [];
            var labels = profitH.map(function(_, i) { return _q + (i + 1); });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [
                        { data: revenueH },
                        { data: profitH }
                    ]
                },
                esgChart: {
                    labels: labels,
                    datasets: [
                        { data: esgH },
                        { data: carbonH }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};

            var profits = history.map(function(r) { return r.results && r.results.profit ? r.results.profit : 0; });
            var revenues = history.map(function(r) { return r.results && r.results.revenue ? r.results.revenue : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var totalRevenue = revenues.reduce(function(s, r) { return s + r; }, 0);
            var avgProfit = totalProfit / profits.length;

            var lastResult = history[history.length - 1].results || {};
            var finalEsg = lastResult.esgRating || 45;
            var finalCarbon = lastResult.carbonIntensity || 100;
            var finalMarkets = lastResult.activeMarkets || 2;

            var finalCash = lastResult.cash;
            if (typeof finalCash !== 'number') finalCash = this.START_CASH;

            var finScore = this._finScore(totalProfit);
            var esgScore = finalEsg;
            var carbonScore = Math.max(0, 100 - finalCarbon);
            var scored = this._composite(finScore, esgScore, carbonScore, totalProfit, finalCash);
            var raw = scored.raw;
            var composite = scored.composite;
            var viability = scored.viability;

            var performanceKey = 'developing';
            if (composite >= 75) performanceKey = 'excellent';
            else if (composite >= 60) performanceKey = 'good';
            else if (composite >= 45) performanceKey = 'satisfactory';
            var performanceLabel = T('perf_' + performanceKey);

            var insights = [];
            if (finalEsg >= 70) insights.push(T('ins_esg_high'));
            if (finalEsg < 50) insights.push(T('ins_esg_low'));
            if (finalCarbon <= 50) insights.push(T('ins_carbon_low'));
            if (finalCarbon > 75) insights.push(T('ins_carbon_high'));
            if (avgProfit > 2000) insights.push(T('ins_profit_high'));
            if (avgProfit < 500) insights.push(T('ins_profit_low'));
            if (finalMarkets >= 6) insights.push(T('ins_markets_high', { n: finalMarkets }));
            if (finalMarkets <= 3) insights.push(T('ins_markets_low'));
            if (viability === 'insolvent') insights.unshift(T('ins_insolvent'));
            else if (viability === 'loss_making') insights.unshift(T('ins_loss_making'));

            return {
                totalProfit: totalProfit,
                totalRevenue: totalRevenue,
                avgProfit: Math.round(avgProfit),
                finalEsgRating: finalEsg,
                finalCarbonIntensity: finalCarbon,
                marketsActive: finalMarkets,
                finalCash: finalCash,
                finScore: Math.round(finScore),
                esgScore: Math.round(esgScore),
                carbonScore: Math.round(carbonScore),
                rawScore: raw,
                viability: viability,
                compositeScore: composite,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: performanceKey,
                performanceKey: performanceKey,
                performanceLabel: performanceLabel,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var s = summary || {};
            var money = function(v) { var n = Math.round(v || 0); return (n < 0 ? '-$' : '$') + Math.abs(n).toLocaleString() + 'M'; };
            var lines = [];
            lines.push(T('done_headline', { score: (s.overallScore != null ? s.overallScore : 0), band: s.performanceLabel || '' }));
            lines.push(T('done_financial', { profit: money(s.totalProfit), revenue: money(s.totalRevenue), cash: money(s.finalCash) }));
            lines.push(T('done_esg', { esg: Math.round(s.finalEsgRating || 0), grade: this._getEsgGrade(s.finalEsgRating || 0), carbon: Math.round(s.finalCarbonIntensity || 0) }));
            lines.push(T('done_reach', { n: s.marketsActive || 0 }));
            lines.push(T('done_breakdown', { fin: s.finScore || 0, esg: s.esgScore || 0, carbon: s.carbonScore || 0 }));
            if (s.viability === 'insolvent') lines.push(T('done_insolvent'));
            else if (s.viability === 'loss_making') lines.push(T('done_loss_making'));
            if (s.insights && s.insights.length) lines.push(s.insights.join(' '));
            return lines.join('\n\n');
        }

        _composite(finScore, esgScore, carbonScore, totalProfit, finalCash) {
            var raw = Math.round((finScore * 0.40) + (esgScore * 0.35) + (carbonScore * 0.25));
            var composite = raw;
            var viability = 'viable';
            if (finalCash <= 0) {
                viability = 'insolvent';
                composite = Math.min(composite, this.CAP_INSOLVENT);
            } else if (totalProfit < 0) {
                viability = 'loss_making';
                composite = Math.min(composite, this.CAP_LOSS);
            }
            return { raw: raw, composite: composite, viability: viability };
        }

        _finScore(totalProfit) {
            var p = totalProfit || 0;
            if (p <= this.FIN_FLOOR) return 0;
            if (p < 0) return 35 * (1 - (p / this.FIN_FLOOR));
            if (p >= this.FIN_CEIL) return 100;
            return 35 + 65 * (p / this.FIN_CEIL);
        }

        _syncControlsFromDecisions(state) {
            var dec = (state && state.decisions) ? state.decisions : null;
            if (!dec) return;
            var set = function(id, val) {
                var el = document.getElementById(id);
                if (el && val !== undefined && val !== null) el.value = String(val);
            };
            set('sustainInput', dec.sustainabilityPct);
            set('pricingSelect', dec.pricingStrategy);
            set('productionSelect', dec.productionMode);
            var exp = document.getElementById('expandSelect');
            if (exp && dec.expandMarket) {
                var ok = false;
                if (exp.options) {
                    for (var i = 0; i < exp.options.length; i++) {
                        if (exp.options[i].value === dec.expandMarket) { ok = true; break; }
                    }
                }
                exp.value = ok ? dec.expandMarket : 'none';
            }
        }

        _applyEndState(state) {
            if (!state) return;
            var maxP = state.maxPeriods || 12;
            var over = (state.currentPeriod > maxP) || ((state.history || []).length >= maxP);
            var controls = document.getElementById('decisionControls');
            var banner = document.getElementById('completionBanner');
            if (controls) controls.style.display = over ? 'none' : '';
            if (banner) banner.style.display = over ? 'block' : 'none';
        }

        getHint(state, results) {
            if (results.eventMessage) return results.eventMessage;
            if (results.profit < 0) return window.mySimulation.t('hint_loss');
            if (state.domainState.esgRating < 40) return window.mySimulation.t('hint_low_esg');
            if (state.domainState.carbonIntensity > 80 && state.currentPeriod > 4) return window.mySimulation.t('hint_high_carbon');
            if (state.domainState.activeMarkets.length < 4 && state.currentPeriod > 6) return window.mySimulation.t('hint_expand');
            if (results.profit > 3000) return window.mySimulation.t('hint_great');
            return null;
        }

